//! Generated by `build.rs`: every `std/*.vibe` module compiled into the binary,
//! so an installed `azra.exe` needs no adjacent source files.

include!(concat!(env!("OUT_DIR"), "/stdlib_embedded.rs"));

/// Names of all embedded standard-library modules.
pub fn names() -> Vec<&'static str> {
    // Keep this list in sync with the generated match arms via a quick scan of
    // the embedded sources; callers use it for REPL/package discovery.
    vec![
        "astar",
        "audit",
        "auth",
        "backup",
        "cache",
        "chart",
        "cli",
        "cli_table",
        "collections",
        "config",
        "cookie",
        "csv",
        "db",
        "diff",
        "eventbus",
        "geo",
        "graph",
        "gui",
        "http",
        "httpclient",
        "i18n",
        "io",
        "jwt",
        "ledger",
        "log",
        "mail",
        "matrix",
        "metrics",
        "middleware",
        "nativegui",
        "orm",
        "pagination",
        "physics",
        "plugin",
        "priority",
        "query",
        "queue",
        "random",
        "ratelimit",
        "report",
        "retry",
        "schedule",
        "search",
        "security",
        "session",
        "set",
        "stack",
        "state",
        "stat",
        "string",
        "stringfmt",
        "template",
        "testing",
        "token",
        "tween",
        "upload",
        "url",
        "validate",
        "vec3",
        "worker",
    ]
    .into_iter()
    .filter(|name| get(name).is_some())
    .collect()
}
